const ico = (name,size=20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.compass}</svg>`;

let persisted={}; try { persisted=JSON.parse(localStorage.getItem(storeKey)||'{}'); } catch {}
let marketPersisted={};try{marketPersisted=JSON.parse(localStorage.getItem(marketStoreKey)||'{}');}catch{}
// Retire only the untouched legacy sample. A changed sample is user work and stays.
if(Array.isArray(persisted.trips))persisted.trips=persisted.trips.filter(t=>!(t.id==='demo'&&(!t.version||t.version===1)));
if(!persisted.trips?.some(t=>t.id===persisted.currentId))persisted.currentId=persisted.trips?.[0]?.id||null;
const state={
  trips: Array.isArray(persisted.trips)?persisted.trips:[],
  currentId:persisted.currentId||null, saved:persisted.saved||[], checked:persisted.checked||{}, posts:persisted.posts||[], name:persisted.name||'旅行者',
  profile:persisted.profile||{interests:['自然','慢游'],pace:'慢一点',budgetLevel:'适中',group:'朋友',departureCity:'',walking:'适中',personalization:true}, events:persisted.events||[],
  page:location.hash.slice(2)||'discover', selectedDay:'all', selectedNode:null, planView:'map', mapLayer:'bright',modal:null, search:'', searchResults:[], searchLoading:false, searchError:'',
  planDestination:'',planPrompt:'',planBusy:false,planError:'',planDraft:null,planRebuild:false,plannerExpanded:false,planPlaces:[],planPlaceQuery:'',planPlaceResults:[],planPlaceBusy:false,planPlaceError:'', bookingTab:'transport', offerKind:null, selectedOffer:null, assistantMessages:[], toast:'', discoverFilter:'全部', communityFilter:'精选',
  assistantOpen:false,assistantBusy:false,modelConfigured:false,modelProvider:'',assistantBottom:null,assistantDragSuppress:false,route:null,routeLoading:false,routeError:'',routeDay:null,plannerTab:'itinerary',placeQuery:'',placeResults:[],placeLoading:false,bookingQuery:'',bookingResults:[],bookingBusy:false,importMatches:[],
  marketCategory:'all',marketSearch:'',marketSort:'featured',marketSaved:marketPersisted.saved||[],marketOrders:marketPersisted.orders||[],marketPlaces:[],marketPlaceQuery:'',marketPlaceBusy:false,marketPlaceError:'',
};
const emptyTrip=()=>({id:'',title:'尚未创建行程',destination:'',origin:state.profile?.departureCity||'你的城市',start:dateOffset(14),end:dateOffset(14),party:1,budget:0,pace:'刚刚好',days:[],expenses:[],checklist:[],version:0});
const trip = () => state.trips.find(t=>t.id===state.currentId)||state.trips[0]||emptyTrip();
const save = () => localStorage.setItem(storeKey, JSON.stringify({schemaVersion:5,trips:state.trips,currentId:state.currentId,saved:state.saved,checked:state.checked,posts:state.posts,name:state.name,profile:state.profile,events:state.events.slice(-150)}));
const saveMarket=()=>localStorage.setItem(marketStoreKey,JSON.stringify({saved:state.marketSaved,orders:state.marketOrders}));
const recordEvent=(type,payload={})=>{if(!state.profile.personalization)return;state.events.push({type,...payload,at:Date.now()});state.events=state.events.slice(-150);save();};
async function searchPlaceApi(query,city){
  if(staticMode)return searchStaticPlaces(query,city);
  for(const endpoint of ['/api/map/search','/api/geo/search']){
    try{const response=await fetch(`${endpoint}?q=${encodeURIComponent(query)}&city=${encodeURIComponent(city)}`);const data=await response.json();if(response.ok&&Array.isArray(data.places))return data.places;}catch{}
  }
  throw new Error('地点服务暂不可用，请稍后重试');
}
const allNodes = () => trip().days.flatMap((day,i)=>day.nodes.map(n=>({...n,day:i+1})));
const invalidateRoute=()=>{state.route=null;state.routeDay=null;state.routeError='';};
function catalogNode(p,day){return {id:`node-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,placeId:p.id||null,day,time:'14:00',duration:`${p.duration||90} 分钟`,name:p.name,type:p.category||'地点',note:p.description||p.address||'地图搜索地点，出发前请核验营业信息。',cost:0,costLabel:'费用待查询',status:'地图参考',lat:Number(p.lat),lng:Number(p.lng),coordinateSystem:'WGS84',source:p.source||'OpenStreetMap Nominatim',icon:p.category==='展馆'?'museum':p.category==='街区'?'landmark':'pin',transport:null};}
function addPlace(p){const day=state.selectedDay==='all'?1:Number(state.selectedDay),d=trip().days[day-1];if(!d)return;if(d.nodes.some(n=>n.placeId===p.id||n.name===p.name)){toast('这一天已经有该地点');return;}const node=catalogNode(p,day);const stay=d.nodes.findIndex(n=>n.type==='住宿'||(n.type==='交通'&&n.time==='17:00'));d.nodes.splice(stay<0?d.nodes.length:stay,0,node);trip().version++;trip().updated=Date.now();invalidateRoute();save();state.modal=null;recordEvent('place_add',{city:trip().destination,placeId:p.id,tags:p.tags||[]});render();toast(`已加入第 ${day} 天：${p.name}`);}
const sumPlanned = () => allNodes().reduce((a,n)=>a+(n.cost||0),0);
const sumSpent = () => trip().expenses.reduce((a,e)=>a+Number(e.amount||0),0);
const navigate = page => { if(page==='new'&&state.page!==page){state.planDraft=null;state.planRebuild=false;state.planError='';state.planPlaces=[];state.planPlaceResults=[];state.planPrompt=state.planDestination?`想去${state.planDestination}玩 3 天，节奏慢一点`:'';}state.page=page; state.modal=null; location.hash='/'+page; render(); window.scrollTo(0,0); };
const toast = message => { state.toast=message; renderToast(); clearTimeout(toast.timer); toast.timer=setTimeout(()=>{state.toast='';renderToast();},3300); };
const renderToast = () => { const el=$('#toast'); if(el) el.innerHTML=state.toast?`<div class="toast-inner">${ico('check',17)} ${safe(state.toast)}</div>`:''; };
const statusBadge = s => `<span class="status-badge ${s==='待查询'?'warning':s==='地图参考'?'info':s==='模拟估算'?'warning':''}">${safe(s)}</span>`;
const navItems=[['discover','发现','compass'],['plan','计划','map'],['journey','出发','route'],['footprints','足迹','footprint'],['profile','我的','user']];

function sidebar(){return `<aside class="sidebar"><button class="brand" data-nav="discover" aria-label="向野首页"><span class="brand-mark"><span></span></span><span class="brand-type">向野<small>XIANGYE</small></span></button><div class="side-section-label">探索旅程</div><nav class="side-nav">${navItems.map(([id,label,icon])=>`<button data-nav="${id}" class="side-nav-item ${state.page===id?'active':''}">${ico(icon,21)}<span>${label}</span>${id==='plan'?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav><div class="side-section-label side-section-spaced">旅途工具</div><nav class="side-nav"><button data-nav="market" class="side-nav-item ${['market','booking'].includes(state.page)?'active':''}">${ico('ticket',21)}<span>机票酒店 · 当地玩乐</span></button><button data-nav="community" class="side-nav-item ${state.page==='community'?'active':''}">${ico('heart',21)}<span>野友社区</span></button><button data-nav="assistant" class="side-nav-item ${state.page==='assistant'?'active':''}">${ico('spark',21)}<span>小野助手</span></button></nav><div class="side-bottom"><div class="side-tip"><div class="tip-icon">${ico('spark',18)}</div><strong>${state.trips.length?'继续打磨行程':'下一站，去哪里？'}</strong><p>${state.trips.length?'查看每天的路线，也可以随时调整想去的地点。':'把想去的地方告诉小野，让旅程慢慢展开。'}</p><button data-nav="${state.trips.length?'plan':'new'}" class="side-tip-btn">${state.trips.length?'查看我的计划':'开始规划'} ${ico('arrow',15)}</button></div><button class="side-profile" data-nav="profile"><span class="avatar">旅</span><span><strong>${safe(state.name)}</strong><small>自由探索者</small></span>${ico('chevron',17)}</button></div></aside>`;}
function mobileNav(){const items=[...navItems.slice(0,3),['market','机酒玩乐','ticket'],...navItems.slice(3)];return `<nav class="mobile-nav">${items.map(([id,label,icon])=>`<button data-nav="${id}" class="${state.page===id||id==='market'&&state.page==='booking'?'active':''}">${ico(icon,21)}<span>${label}</span></button>`).join('')}</nav>`;}
function topbar(title='发现更多美好',sub=''){return `<header class="topbar"><div class="topbar-location">${ico('pin',17)} <span>从 ${safe(trip().origin)} 出发</span><span class="topbar-divider"></span><span class="topbar-greeting">${safe(title)}</span></div><div class="topbar-actions"><button class="top-icon" data-nav="search" aria-label="搜索">${ico('search',20)}</button><button class="top-icon" data-nav="assistant" aria-label="小野助手">${ico('spark',20)}</button><button class="top-avatar" data-nav="profile" aria-label="我的">旅</button></div></header>${sub?`<div class="mobile-page-label">${safe(sub)}</div>`:''}`;}
function sectionHeader(kicker,title,link='',action=''){return `<div class="section-heading"><div><span class="eyebrow">${safe(kicker)}</span><h2>${safe(title)}</h2></div>${link?`<button class="text-link" data-nav="${action}">${safe(link)} ${ico('arrow',17)}</button>`:''}</div>`;}
function destinationCard(d,wide=false){return `<div class="destination-wrap"><button class="destination-card ${wide?'wide':''}" data-destination="${d.id}" style="--card-color:${d.color}"><img src="${d.image}" alt="${safe(d.name)}风景" loading="lazy"/><span class="image-shade"></span><span class="card-topline">${safe(d.province)} · ${safe(d.type)}</span><span class="card-content"><strong>${safe(d.name)}</strong><small>${safe(d.tagline)}</small><span class="card-arrow">${ico('arrow',20)}</span></span></button><button class="save-destination ${state.saved.includes(d.id)?'saved':''}" data-save="${d.id}" aria-label="${state.saved.includes(d.id)?'取消收藏':'收藏'}${safe(d.name)}">${ico('heart',16)}</button></div>`;}
function discoverJourneyCard(){
  const t=trip(),photo=destinations.find(d=>d.name===t.destination)?.image||photos.hero;
  const located=t.days.flatMap(d=>d.nodes).filter(n=>n.lat!=null&&n.lng!=null).length;
  return `<section class="discover-journey" style="--journey-photo:url('${photo}')"><div class="discover-journey-copy"><span class="discover-journey-kicker">YOUR NEXT JOURNEY / 我的行程</span><h2>${safe(t.destination)}，<br/>已经在路上。</h2><p>${safe(t.origin)}出发 · ${formatDate(t.start)}—${formatDate(t.end)} · ${t.days.length} 天 ${Math.max(0,t.days.length-1)} 晚</p><div class="discover-journey-meta"><span>${ico('pin',16)} ${located} 个已定位地点</span><span>${ico('wallet',16)} ${yen(t.budget)} 计划预算</span></div><div class="discover-journey-actions"><button data-nav="plan">继续整理行程 ${ico('arrow',17)}</button><button data-nav="new">再建一段旅程</button></div></div><div class="discover-journey-stamp">XIANGYE<br/>TRIP STUDIO</div></section>`;
}
function discoverPage(){
  const ranked=recommendDestinations(destinations,state.profile,state.profile.personalization?state.events:[],state.trips);
  const filtered=state.discoverFilter==='全部'?ranked:ranked.filter(d=>d.type.includes(state.discoverFilter)||({'城市':['杭州','成都'],'自然':['大理','黄山','乌兰布统'],'周末':['杭州','黄山']}[state.discoverFilter]||[]).includes(d.name));
  const lead=state.trips.length?discoverJourneyCard():`<section class="hero" style="background-image:linear-gradient(90deg,rgba(17,47,35,.80),rgba(17,47,35,.42) 47%,rgba(0,0,0,.05)),url('${photos.hero}')"><div class="hero-content"><span class="hero-pill">${ico('spark',14)} 向野灵感提案</span><h2>这周末，<br/>去山野间透透气。</h2><p>从城市出走，在风里找回自己的节奏。</p><button class="light-btn" data-nav="new">规划我的旅程 ${ico('arrow',18)}</button></div><div class="hero-index">01 <span>/</span> 04</div></section>`;
  return `${topbar('把日子过成喜欢的样子','发现')}<main class="main-content discover-page"><div class="intro-line"><span class="eyebrow">GOOD DAY, EXPLORER</span><h1>去远方，也去<br/><em>遇见自己。</em></h1><p>路线不必太满，风景自会到来。<br/>从一个念头开始，规划一场刚刚好的旅行。</p></div>${lead}<section class="quick-plan"><div class="quick-heading"><span class="quick-icon">${ico('route',22)}</span><div><strong>一句话，开始一段旅程</strong><small>小野会陪你把沿途安排得刚刚好</small></div></div><button class="quick-input" data-nav="new"><span>比如：从上海出发，去杭州过一个松弛的周末…</span>${ico('arrow',18)}</button></section><section class="dest-section">${sectionHeader('EXPLORE DESTINATIONS','灵感目的地','查看全部','search')}<div class="filter-row">${['全部','周末','自然','城市'].map(f=>`<button data-filter="${f}" class="filter-chip ${state.discoverFilter===f?'active':''}">${f}</button>`).join('')}</div><div class="dest-grid">${filtered.map((d,i)=>destinationCard(d,i===0)).join('')}</div></section><section class="story-section">${sectionHeader('STORIES FROM THE ROAD','路上的故事','走进社区','community')}<div class="story-grid">${samplePosts.slice(0,2).map(p=>`<button class="story-card" data-story="${p.id}"><img src="${p.image}" alt="${safe(p.title)}" loading="lazy"/><div><span>${safe(p.city)} · 野友来信</span><strong>${safe(p.title)}</strong><small>${safe(p.text)}</small></div></button>`).join('')}</div></section></main>`;
}

function pageTitle(kicker,title,desc='',buttons=''){return `<div class="page-title-row"><div><span class="eyebrow">${safe(kicker)}</span><h1>${safe(title)}</h1>${desc?`<p>${safe(desc)}</p>`:''}</div>${buttons}</div>`;}
function tripSwitcher(){return `<div class="trip-switch"><select id="tripSelect" aria-label="切换行程">${state.trips.map(t=>`<option value="${safe(t.id)}" ${t.id===trip().id?'selected':''}>${safe(t.title)}</option>`).join('')}</select><button class="outline-btn" data-nav="new">${ico('plus',17)} 新建行程</button></div>`;}
function tripStats(){return `<div class="trip-stats"><div><span>旅行天数</span><strong>${trip().days.length}<small> 天</small></strong></div><div><span>计划预算</span><strong>${yen(trip().budget)}</strong></div><div><span>已规划估算</span><strong>${yen(sumPlanned())}</strong></div><div><span>预算余量</span><strong class="${trip().budget-sumPlanned()<0?'danger':''}">${yen(trip().budget-sumPlanned())}</strong></div></div>`;}
function dayTabs(){return `<div class="day-tabs"><button data-day="all" class="${state.selectedDay==='all'?'active':''}">全部日期</button>${trip().days.map((d,i)=>`<button data-day="${i+1}" class="${state.selectedDay===i+1?'active':''}"><span>DAY 0${i+1}</span>${formatDate(addDate(trip().start,i))}</button>`).join('')}</div>`;}
function nodeCard(n,index,compact=false){return `<button class="node-card ${state.selectedNode===n.id?'selected':''} ${compact?'compact':''}" data-node="${n.id}"><span class="node-time">${safe(n.time)}</span><span class="node-track"><span class="node-dot ${n.done?'done':''}">${ico(n.icon||'pin',15)}</span></span><span class="node-main"><span class="node-title">${safe(n.name)} ${n.locked?'<span class="tiny-lock">已锁定</span>':''}${n.done?'<span class="tiny-done">已完成</span>':''}</span><span class="node-sub">${safe(n.type)} · ${safe(n.duration)} · ${safe(n.costLabel)}</span>${!compact&&n.transport?`<span class="node-transport">${ico('route',13)} 下一段：${safe(n.transport)}</span>`:''}</span>${ico('chevron',17)}</button>`;}
function timeline(){const days=state.selectedDay==='all'?trip().days.map((d,i)=>[d,i]):[[trip().days[state.selectedDay-1],state.selectedDay-1]];return `<div class="timeline-scroll">${days.map(([day,i])=>`<div class="timeline-day"><div class="timeline-day-head"><div><span class="eyebrow">DAY 0${i+1} · ${formatDate(addDate(trip().start,i))}</span><h3>${safe(day.title)}</h3></div><span class="day-count">${day.nodes.length} 个地点</span></div>${day.nodes.map((n,j)=>nodeCard(n,j)).join('')}</div>`).join('')}</div>`;}
function calendarView(){return `<div class="calendar-grid">${trip().days.map((day,i)=>`<button class="calendar-card" data-day="${i+1}"><div class="calendar-card-top"><span>DAY 0${i+1}</span>${ico('arrow',17)}</div><strong>${formatDate(addDate(trip().start,i))}</strong><h3>${safe(day.title)}</h3><p>${safe(day.note)}</p><div class="calendar-mini-route">${day.nodes.slice(0,3).map(n=>`<span>${safe(n.name)}</span>`).join('')}</div><div class="calendar-cost">本日估算 <b>${yen(day.nodes.reduce((a,n)=>a+(n.cost||0),0))}</b></div></button>`).join('')}</div>`;}
function planPlacePicker(){return `<div class="plan-place-picker"><div class="plan-place-heading"><div><strong>${ico('pin',17)} 手动添加必去地点</strong><p>从地图搜索并选择真实地点，可指定哪一天；所选地点会优先进入草稿。</p></div><span>${state.planPlaces.length} 个已选</span></div><form id="planPlaceSearchForm"><input name="query" value="${safe(state.planPlaceQuery)}" placeholder="搜索：公主湖、将军泡子、餐厅…" maxlength="80" required/><button class="outline-btn" type="submit" ${state.planPlaceBusy?'disabled':''}>${state.planPlaceBusy?'搜索中…':'搜索地点'}</button></form>${state.planPlaceError?`<p class="natural-plan-error">${safe(state.planPlaceError)}</p>`:''}${state.planPlaceResults.length?`<div class="plan-place-results">${state.planPlaceResults.slice(0,8).map((p,i)=>`<div><span><strong>${safe(p.name)}</strong><small>${safe(p.city||'')} · ${safe(p.address||'地址待核验')}</small></span><button type="button" data-plan-place-add="${i}">加入</button></div>`).join('')}</div>`:''}${state.planPlaces.length?`<div class="plan-place-selected">${state.planPlaces.map((item,i)=>`<div><span>${ico('pin',14)} ${safe(item.place.name)}</span><select data-plan-place-day="${i}" aria-label="${safe(item.place.name)}安排日期"><option value="0" ${!item.day?'selected':''}>自动安排</option>${Array.from({length:14},(_,j)=>`<option value="${j+1}" ${Number(item.day)===j+1?'selected':''}>第 ${j+1} 天</option>`).join('')}</select><button type="button" data-plan-place-remove="${i}" aria-label="移除${safe(item.place.name)}">×</button></div>`).join('')}</div>`:''}</div>`;}
function naturalPlanner(){
  const exists=!!state.trips.length,mode=state.page==='new'||!exists||state.planRebuild?'create':'adjust';
  if(exists&&state.page==='plan'&&!state.plannerExpanded&&!state.planDraft&&!state.planError&&!state.planBusy)return `<section class="planner-compact"><span class="planner-compact-icon">${ico('spark',23)}</span><div><span>AI TRIP EDITOR</span><strong>这段${safe(trip().destination)}旅程，还想怎么安排？</strong><p>一句话调整行程，也可以搜索地点后手动安排。</p></div><div class="planner-compact-actions"><button data-action="openPlanner">${ico('spark',16)} 智能调整</button><button data-action="rebuildTrip">${ico('route',16)} 重新规划</button></div></section>`;
  const example=mode==='create'?'例如：下个月从上海去成都玩 3 天，两个人预算 3000，想看熊猫和吃火锅，节奏慢一点':'例如：把第二天的景点换成一间博物馆，节奏慢一点，预算改为 3500';
  const draft=state.planDraft;
  return `<section class="natural-planner ${exists?'has-trip':''}"><div class="natural-planner-intro"><span class="eyebrow">YOUR WORDS, YOUR JOURNEY</span><h1>${state.planRebuild?'重新安排每一天。':mode==='create'?'说说你想去哪里。':'这段旅程，听你的。'}</h1><p>${state.planRebuild?'重新生成逐日路线，核对草稿后才会覆盖当前行程。':mode==='create'?'写下目的地、天数、预算和喜欢的玩法。小野先给你一份可核对的草稿。':'告诉小野想增加、移除或调整什么；确认前，原行程不会改变。'}</p>${exists&&state.page==='plan'&&!state.planDraft?`<button class="planner-collapse" data-action="closePlanner">收起规划器 ↑</button>`:''}${exists&&state.page!=='new'?`<div class="plan-mode-actions"><button type="button" data-action="adjustTrip" class="${!state.planRebuild?'active':''}">调整现有行程</button><button type="button" data-action="rebuildTrip" class="${state.planRebuild?'active':''}">重新规划此行程</button></div>`:''}</div><form id="naturalPlanForm"><label for="planPrompt">${mode==='create'?'描述这次旅行':'描述你想怎样调整'}</label><textarea id="planPrompt" name="prompt" rows="3" maxlength="800" placeholder="${safe(example)}" required>${safe(state.planPrompt)}</textarea><div class="natural-planner-controls"><span>${ico('spark',16)} ${staticMode?'网页精选地点规划':'本地模型辅助解析'} · 真实坐标地点 · 确认后保存</span><button class="primary-btn" type="submit" ${state.planBusy?'disabled':''}>${state.planBusy?'正在理解你的想法…':mode==='create'?'生成行程草稿':'预览调整'} ${ico('arrow',16)}</button></div></form>${planPlacePicker()}${state.planError?`<div class="natural-plan-error" role="alert">${safe(state.planError)}</div>`:''}${draft?planDraftMarkup(draft):''}</section>`;
}
function planDraftMarkup(draft){const t=draft.trip;return `<section class="plan-draft" id="planDraft"><div class="plan-draft-head"><div><span class="eyebrow">PREVIEW / 尚未保存</span><h2>${safe(t.title)}</h2><p>${safe(draft.summary)}</p></div><span class="draft-status">待你确认</span></div><div class="plan-draft-days">${t.days.map((d,i)=>`<article><span>DAY ${String(i+1).padStart(2,'0')} · ${formatDate(d.date)}</span><strong>${safe(d.title)}</strong><p>${d.nodes.map(n=>`${safe(n.name)}${n.lat==null?` <small>${n.status==='待查询'?'待确认':'模拟'}</small>`:''}`).join(' <em>→</em> ')}</p></article>`).join('')}</div>${draft.diff?.length?`<div class="plan-draft-diff">${draft.diff.map(d=>`<div>第 ${d.day} 天：${d.removed.map(n=>`<span class="removed">移除 ${safe(n)}</span>`).join(' ')} ${d.added.map(n=>`<span class="added">加入 ${safe(n)}</span>`).join(' ')}</div>`).join('')}</div>`:''}${draft.notice?`<p class="plan-draft-notice">${safe(draft.notice)}</p>`:''}<form id="planConfirmForm"><div class="plan-draft-fields"><label>出发城市<input name="origin" value="${safe(t.origin)}" maxlength="30" required/></label><label>出发日期<input name="start" type="date" min="${dateOffset(0)}" value="${safe(t.start)}" required/></label><label>同行人数<input name="party" type="number" min="1" max="20" value="${t.party}" required/></label><label>预算（元）<input name="budget" type="number" min="200" max="1000000" value="${t.budget}" required/></label><label>旅行节奏<select name="pace">${['慢一点','刚刚好','多走走'].map(x=>`<option ${t.pace===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="plan-draft-actions"><button class="outline-btn" type="button" data-action="discardPlanDraft">放弃草稿</button><button class="primary-btn" type="submit">确认并${draft.mode==='create'?'写入计划':draft.mode==='rebuild'?'重排计划':'保存调整'} ${ico('check',17)}</button></div></form></section>`;}
function planPage(){
  if(!state.trips.length)return `${topbar('从一个想法开始','计划')}<main class="plan-empty">${naturalPlanner()}<div class="plan-empty-after"><span>01 写下想法</span><span>02 核对草稿</span><span>03 确认保存</span></div></main>`;
  if(state.planView==='map')return `${topbar('把想去的地方，连成一段好旅程','计划')}${naturalPlanner()}${plannerMarkup({trip:trip(),state,ico,safe,yen,formatDate,addDate,statusBadge,allNodes:allNodes()})}`;
  return `${topbar('把想去的地方，连成一段好旅程','计划')}<main class="main-content plan-page"><button class="back-link" data-view="map">${ico('back',18)} 返回地图工作台</button>${pageTitle('TRIP DETAILS',state.planView==='budget'?'预算与行前清单':'多日概览','与地图使用同一份行程数据。')}<div class="plan-toolbar"><div class="segmented"><button data-view="map">${ico('map',17)} 地图工作台</button><button data-view="calendar" class="${state.planView==='calendar'?'active':''}">${ico('calendar',17)} 行程日历</button><button data-view="budget" class="${state.planView==='budget'?'active':''}">${ico('wallet',17)} 预算清单</button></div></div>${state.planView==='calendar'?calendarView():budgetView()}</main>`;
}
function budgetView(){const t=trip(),planned=sumPlanned(),spent=sumSpent();return `<div class="budget-grid"><section class="panel budget-overview"><span class="eyebrow">BUDGET OVERVIEW</span><h3>旅费概览</h3><div class="budget-number">${yen(t.budget)} <small>总预算 · ${t.party} 人</small></div><div class="progress-track"><span style="width:${Math.min(100,planned/t.budget*100)}%"></span></div><div class="budget-rows"><div><span>已规划估算</span><b>${yen(planned)}</b></div><div><span>已记录支出</span><b>${yen(spent)}</b></div><div><span>可用预算</span><b class="green-text">${yen(t.budget-planned)}</b></div></div><p class="muted-small">已规划金额不包含待查询的车票、门票和酒店实时价，预算余量并非最终可用金额。</p></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">EXPENSES</span><h3>我的记账</h3></div><button class="small-outline" data-modal="expense">${ico('plus',15)} 记一笔</button></div>${t.expenses.length?`<div class="expense-list">${t.expenses.map(e=>`<div class="expense-item"><span class="expense-icon">${ico(e.category==='餐饮'?'coffee':e.category==='住宿'?'bed':'wallet',17)}</span><div><b>${safe(e.name)}</b><small>${safe(e.category)} · ${safe(e.date)}</small></div><strong>${yen(e.amount)}</strong><button data-delete-expense="${e.id}" aria-label="删除支出">${ico('close',15)}</button></div>`).join('')}</div>`:`<div class="empty-mini">${ico('wallet',28)}<strong>还没有实际支出</strong><span>路上的每一笔，都可以记在这里。</span></div>`}</section><section class="panel checklist-panel"><div class="panel-heading"><div><span class="eyebrow">BEFORE YOU GO</span><h3>行前清单</h3></div><span class="completion">${t.checklist.filter(c=>c.done).length}/${t.checklist.length} 完成</span></div><div class="checklist">${t.checklist.map(c=>`<label><input type="checkbox" data-check="${c.id}" ${c.done?'checked':''}/><span>${safe(c.text)}</span></label>`).join('')}</div><form id="checklistForm" class="add-inline"><input name="item" placeholder="添加待办事项" maxlength="60" required/><button aria-label="添加">${ico('plus',17)}</button></form></section><section class="panel"><span class="eyebrow">DAILY BREAKDOWN</span><h3>按天查看</h3><div class="daily-bars">${t.days.map((day,i)=>{const c=day.nodes.reduce((a,n)=>a+n.cost,0);return `<div><span>第 ${i+1} 天 <small>${formatDate(addDate(t.start,i))}</small></span><div class="bar-track"><i style="width:${Math.max(8,c/Math.max(1,planned)*100)}%"></i></div><b>${yen(c)}</b></div>`}).join('')}</div><button class="link-button" data-nav="market">去查看交通与住宿 ${ico('arrow',16)}</button></section></div>`;}

function newPage(){return `${topbar('新的旅程，从一句话开始','新建计划')}<main class="plan-empty new-plan-page"><button class="back-link" data-nav="plan">${ico('back',18)} 返回我的行程</button>${naturalPlanner()}<div class="plan-empty-after"><span>01 写下想法</span><span>02 核对草稿</span><span>03 确认保存</span></div></main>`;}

function journeyPage(){if(!allNodes().length)return `${topbar('现在，出发吧','出发')}<main class="main-content journey-page">${pageTitle('ON THE ROAD','先写下你的下一站','确认一份旅行计划后，这里会显示当天的下一站与行前提醒。')}<button class="primary-btn" data-nav="plan">开始规划 ${ico('arrow',17)}</button></main>`;const current=allNodes().find(n=>!n.done)||allNodes()[0], done=allNodes().filter(n=>n.done).length;return `${topbar('现在，出发吧','出发')}<main class="main-content journey-page">${pageTitle('ON THE ROAD','今天，向野出发','不用急，跟着自己的节奏走。')}<div class="journey-hero" style="background-image:linear-gradient(90deg,rgba(13,52,39,.87),rgba(13,52,39,.23)),url('${photos.huangshan}')"><span>YOUR JOURNEY STARTS HERE</span><h2>${safe(trip().title)}</h2><p>${formatDate(trip().start)} 出发 · 已完成 ${done}/${allNodes().length} 站</p><button class="light-btn" data-nav="plan">查看完整路线 ${ico('arrow',17)}</button></div><div class="journey-grid"><section class="panel next-stop"><span class="eyebrow">NEXT STOP</span><div class="next-icon">${ico(current.icon,24)}</div><span>下一站 · 第 ${current.day} 天</span><h3>${safe(current.name)}</h3><p>${safe(current.note)}</p><div class="next-meta"><span>${ico('clock',16)} ${safe(current.time)}</span><span>${ico('pin',16)} ${safe(current.type)}</span></div><div class="next-buttons"><button class="primary-btn" data-action="completeCurrent">${ico('check',17)} 标记已到达</button><button class="outline-btn" data-node="${current.id}">查看地点</button></div></section><section class="panel journey-reminder"><span class="eyebrow">GENTLE REMINDER</span><h3>出发前，确认一下</h3><div class="reminder-list"><div>${ico('ticket',19)} <span>城际班次与车票 <small>待向服务方查询</small></span></div><div>${ico('bed',19)} <span>酒店房态与订单 <small>预订后请核对地址和时间</small></span></div><div>${ico('sun',19)} <span>天气与开放时间 <small>出发当天再次确认</small></span></div></div><button class="link-button" data-action="showBudget">查看行前清单 ${ico('arrow',16)}</button></section></div></main>`;}

function searchPage(){const q=state.search.trim().toLowerCase(),items=destinations.filter(d=>!q||(`${d.name}${d.province}${d.type}`).toLowerCase().includes(q));return `${topbar('世界很大，慢慢发现','搜索')}<main class="main-content search-page">${pageTitle('FIND YOUR PLACE','想去哪里看看？','搜索城市或目的地，让一段新旅程从这里开始。')}<div class="search-box">${ico('search',22)}<input id="searchInput" value="${safe(state.search)}" placeholder="试试搜索：杭州、自然、周末…" autocomplete="off"/><button data-action="search">搜索 ${ico('arrow',17)}</button></div><div class="search-suggestions"><span>热门搜索</span>${['杭州','大理','成都','黄山'].map(x=>`<button data-query="${x}">${x}</button>`).join('')}</div>${state.searchLoading?'<div class="search-loading">正在向地图服务查找地点…</div>':''}${state.searchError?`<div class="search-error">${safe(state.searchError)}</div>`:''}${state.searchResults.length?`<section class="search-result-section">${sectionHeader('MAP SEARCH','地图地点')}<div class="place-results">${state.searchResults.map(p=>`<div class="place-result">${ico('pin',19)}<div><strong>${safe(p.name)}</strong><small>${safe(p.address||p.city||'地址待核验')} · ${safe(p.source)}</small></div><button data-action="addSearchedPlace" data-place="${safe(p.name)}">加入行程</button></div>`).join('')}</div></section>`:''}<section class="search-result-section">${sectionHeader('CURATED PLACES',q?'匹配的目的地':'你可能会喜欢')}<div class="dest-grid search-dest">${items.length?items.map(d=>destinationCard(d)).join(''):'<div class="empty-wide">没有匹配的精选目的地。可以使用上面的地图地点搜索。</div>'}</div></section></main>`;}

function marketPage(){return `${topbar('把期待变成沿途风景','机酒玩乐')}${marketMarkup({trip:trip(),state,ico,safe,yen,formatDate})}`;}
function communityPage(){const posts=[...state.posts.map(p=>({...p,image:photos.coffee})),...samplePosts];return `${topbar('与同路的人，分享沿途的光','社区')}<main class="main-content community-page">${pageTitle('WILD STORIES','野友们的故事','旅行不只有目的地，还有一路上遇见的生活。',`<button class="primary-btn" data-modal="post">${ico('plus',17)} 写一篇动态</button>`)}<div class="community-tabs">${['精选','最新','我发布的'].map(f=>`<button data-community="${f}" class="${state.communityFilter===f?'active':''}">${f}</button>`).join('')}</div><div class="community-grid">${(state.communityFilter==='我发布的'?state.posts:posts).map(p=>`<article class="post-card" data-story="${p.id}"><img src="${p.image}" alt="${safe(p.title)}" loading="lazy"/><div class="post-body"><span class="post-city">${ico('pin',13)} ${safe(p.city)}</span><h3>${safe(p.title)}</h3><p>${safe(p.text)}</p><div class="post-footer"><span class="post-avatar" style="background:${p.color||'#b9c9ae'}">${safe(p.initial)}</span><b>${safe(p.author)}</b><span class="post-like">${ico('heart',16)} ${p.likes||0}</span></div></div></article>`).join('')||'<div class="empty-wide">还没有发布的动态。写下旅途里的一件小事吧。</div>'}</div><p class="community-note">演示动态为示例内容。本地发布仅保存在此浏览器中，不会公开上传或进入审核。</p></main>`;}
function footprintsPage(){const done=allNodes().filter(n=>n.done);return `${topbar('每一步，都算数','足迹')}<main class="main-content footprints-page">${pageTitle('YOUR FOOTPRINTS','走过的路，都会发光','把抵达的瞬间，慢慢收进自己的旅行地图。')}<div class="footprint-hero"><div><span class="eyebrow">MY TRAVEL JOURNAL</span><h2>世界很大，<br/>你已经出发。</h2><p>已记录 ${done.length} 个到达的地点</p><button class="light-btn" data-nav="journey">继续旅程 ${ico('arrow',17)}</button></div><div class="footprint-art">${ico('footprint',110)}</div></div>${sectionHeader('PLACES I HAVE BEEN','我的到达记录')}<div class="footprint-list">${done.length?done.map(n=>`<div class="footprint-item"><span class="footprint-item-icon">${ico(n.icon,20)}</span><div><strong>${safe(n.name)}</strong><span>${safe(trip().destination)} · 第 ${n.day} 天 · ${safe(n.time)}</span></div>${ico('check',18)}</div>`).join(''):`<div class="empty-wide footprint-empty">${ico('pin',34)}<strong>足迹，从第一站开始</strong><p>在「出发」或行程地点中标记到达，足迹就会出现在这里。</p><button class="outline-btn" data-nav="journey">查看下一站</button></div>`}</div></main>`;}

function profilePage(){const p=state.profile,recs=recommendDestinations(destinations,p,p.personalization?state.events:[],state.trips);return `${topbar('把旅程过成自己的样子','我的')}<main class="main-content profile-page">${pageTitle('MY CORNER','我的向野','设置旅行偏好，向野会结合你保存的行程与浏览记录调整推荐。')}<div class="profile-grid"><section class="profile-card panel"><div class="profile-avatar">旅</div><div><span class="eyebrow">TRAVELER PROFILE</span><h2>${safe(state.name)}</h2><p>${safe(p.departureCity||trip().origin)}出发 · ${safe(p.pace||'自由节奏')} · 喜欢${safe((p.interests||[]).slice(0,2).join('、')||'随心探索')}</p></div><button class="small-outline" data-modal="profile">编辑名字</button></section><section class="profile-stat panel"><span>我的行程</span><strong>${state.trips.length}</strong><small>段旅程</small></section><section class="profile-stat panel"><span>收藏灵感</span><strong>${state.saved.length}</strong><small>个目的地</small></section></div><section class="panel preference-panel"><span class="eyebrow">TRAVEL DNA</span><h3>我的旅行偏好</h3><p>选择你喜欢的主题，推荐会结合当前行程、收藏与最近浏览记录重新排序。</p><div class="interest-grid">${['自然','慢游','人文','美食','摄影','博物馆','徒步','城市','亲子','街区'].map(tag=>`<button data-interest="${tag}" class="${(p.interests||[]).includes(tag)?'active':''}">${tag}</button>`).join('')}</div><form id="preferencesForm" class="preferences-form"><label>常用出发地<input name="departureCity" value="${safe(p.departureCity||'')}" maxlength="30"/></label><label>旅行节奏<select name="pace">${['慢一点','刚刚好','多走走'].map(v=>`<option ${p.pace===v?'selected':''}>${v}</option>`).join('')}</select></label><label>预算习惯<select name="budgetLevel">${['经济','适中','舒适'].map(v=>`<option ${p.budgetLevel===v?'selected':''}>${v}</option>`).join('')}</select></label><label>同行方式<select name="group">${['独行','朋友','伴侣','家庭'].map(v=>`<option ${p.group===v?'selected':''}>${v}</option>`).join('')}</select></label><label>步行接受度<select name="walking">${['少走路','适中','喜欢步行'].map(v=>`<option ${p.walking===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="preference-check"><input name="personalization" type="checkbox" ${p.personalization?'checked':''}/> 使用本机浏览记录优化推荐</label><button class="primary-btn">保存偏好</button></form><small class="preference-privacy">浏览记录只保存在当前浏览器，可以随时清除。</small></section><section class="profile-personalized">${sectionHeader('FOR YOU','为你挑选')}<div class="dest-grid">${recs.slice(0,3).map(d=>destinationCard(d)).join('')}</div><p>排序依据：偏好主题、已有行程、收藏和近期浏览。当前为可解释的本地打分推荐，不代表平台热门或实时热度。</p></section><div class="profile-lists"><section class="panel"><span class="eyebrow">MY SPACE</span><h3>常用入口</h3><button class="profile-row" data-nav="plan">${ico('map',19)} <span>我的行程</span>${ico('chevron',17)}</button><button class="profile-row" data-nav="market">${ico('ticket',19)} <span>机酒与当地玩乐</span>${ico('chevron',17)}</button><button class="profile-row" data-nav="footprints">${ico('footprint',19)} <span>旅行足迹</span>${ico('chevron',17)}</button></section><section class="panel"><span class="eyebrow">PRIVACY</span><h3>本地数据</h3><div class="setting-row"><div>${ico('wallet',19)} <span>数据保存<small>仅当前浏览器</small></span></div><span>本机</span></div><button class="profile-row" data-action="clearHistory">${ico('trash',19)} <span>清除推荐浏览记录</span>${ico('chevron',17)}</button><button class="profile-row danger-row" data-modal="clear">${ico('trash',19)} <span>清除全部本地数据</span>${ico('chevron',17)}</button></section></div></main>`;}

function assistantPage(){const messages=state.assistantMessages;return `${topbar('有问题，问问小野','小野助手')}<main class="main-content assistant-page">${pageTitle('YOUR TRAVEL COMPANION','小野，陪你慢慢走','问行程、找灵感，或说说想怎样调整。')}<div class="assistant-layout"><div class="chat-panel panel"><div class="chat-head"><span class="assistant-avatar">${ico('spark',22)}</span><div><strong>小野</strong><small>行程助手 · ${state.modelConfigured?(state.modelProvider||'模型已连接'):'模型待配置'}</small></div><span class="online-dot"></span></div><div class="chat-messages" id="chatMessages"><div class="chat-message bot"><span class="mini-avatar">${ico('spark',16)}</span><div class="bubble">你好呀！我可以帮你看看「${safe(trip().title)}」的预算、下一站和行程安排。你也可以说说想怎么调整，我会给出建议，具体修改由你在计划页确认。</div></div>${messages.map(m=>`<div class="chat-message ${m.role}">${m.role==='bot'?`<span class="mini-avatar">${ico('spark',16)}</span>`:''}<div class="bubble">${safe(m.text)}${m.action?`<button class="chat-action" data-chat-action="${m.action}">${safe(m.actionLabel||'查看')} ${ico('arrow',14)}</button>`:''}</div></div>`).join('')}</div><div class="chat-chips">${['这趟预算够吗？','下一站是什么？','想换一个室内地点','查看行前清单'].map(q=>`<button data-prompt="${q}">${q}</button>`).join('')}</div><form id="chatForm" class="chat-input"><input name="message" placeholder="跟小野说说你的想法…" maxlength="240" autocomplete="off" required/><button aria-label="发送">${ico('send',20)}</button></form></div><aside class="assistant-aside"><span class="eyebrow">TRIP CONTEXT</span><h3>正在参考的行程</h3><div class="assist-trip-card"><strong>${safe(trip().title)}</strong><span>${formatDate(trip().start)}—${formatDate(trip().end)}</span><div><span>预算余量</span><b>${yen(trip().budget-sumPlanned())}</b></div></div><div class="assistant-disclaimer">${ico('spark',20)}<p>${staticMode?'公开网页使用基础助手，可查看行程信息；自由问答需要另行部署模型服务。任何改动都需要你确认。':'模型通过本地服务端连接。未配置密钥时会明确提示；任何行程改动都需要你在界面确认。'}</p></div></aside></div></main>`;}

function modalHtml(){if(!state.modal)return ''; const type=state.modal.type, node=state.modal.nodeId?allNodes().find(n=>n.id===state.modal.nodeId):null; let body='';
if(type==='marketOffer'||type==='marketCheckout'){const offer=mockOffers.find(o=>o.id===state.modal.offerId);body=type==='marketOffer'?marketOfferModal({offer,trip:trip(),ico,safe,yen}):marketCheckoutModal({offer,trip:trip(),ico,safe,yen});}
if(type==='tripSettings'){body=`<div class="modal-heading"><span class="eyebrow">TRIP SETTINGS</span><h2>调整这段旅程</h2><p>修改出发日期会保持当前旅行天数，并同步更新每天的日期。</p></div><form id="tripSettingsForm" class="modal-form"><label>出发城市<input name="origin" value="${safe(trip().origin)}" maxlength="30" required/></label><label>出发日期<input name="start" type="date" value="${safe(trip().start)}" required/></label><label>同行人数<input name="party" type="number" min="1" max="20" value="${trip().party}" required/></label><label>整单预算（元）<input name="budget" type="number" min="200" value="${trip().budget}" required/></label><label>旅行节奏<select name="pace">${['慢一点','刚刚好','多走走'].map(x=>`<option value="${x}" ${trip().pace===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="primary-btn">保存旅程设置</button></form>`;}
if(type==='import'){body=`<div class="modal-heading"><span class="eyebrow">IMPORT IDEAS</span><h2>从攻略文字提取地点</h2><p>粘贴文章摘录或旅行笔记。只识别${safe(trip().destination)}精选地点名称；内容不会上传。</p></div><form id="importForm" class="modal-form"><label>攻略文字<textarea name="content" rows="5" maxlength="5000" placeholder="例如：第一天去西湖，第二天去灵隐寺和浙江省博物馆…" required></textarea></label><button class="primary-btn">提取地点</button></form>${state.importMatches.length?`<div class="replacement-list">${state.importMatches.map(p=>`<button class="replacement-option" data-add-catalog="${safe(p.id)}"><span class="replacement-icon">${ico('pin',19)}</span><span><strong>${safe(p.name)}</strong><small>${safe(p.description)}</small></span>${ico('plus',17)}</button>`).join('')}</div><button class="primary-btn" data-action="addImported">全部加入第 ${state.selectedDay==='all'?1:state.selectedDay} 天</button>`:''}`;}
if(type==='placeSearch'){const catalog=placeCatalog.filter(p=>p.city===trip().destination).filter(p=>!state.placeQuery||`${p.name}${p.category}${p.tags.join('')}`.includes(state.placeQuery));body=`<div class="modal-heading"><span class="eyebrow">ADD A REAL PLACE</span><h2>添加真实地点</h2><p>加入第 ${state.selectedDay==='all'?1:state.selectedDay} 天。精选地点带有核对过的地图坐标，也可以搜索百度地图与 OpenStreetMap。</p></div><form id="placeSearchForm" class="modal-form"><label>搜索地点<input name="query" value="${safe(state.placeQuery)}" placeholder="例如：西湖、咖啡馆、博物馆" required maxlength="80"/></label><button class="primary-btn">搜索地图地点</button></form>${state.placeLoading?'<p class="muted-small">正在查找地点…</p>':''}${state.searchError?`<p class="search-error">${safe(state.searchError)}</p>`:''}<div class="replacement-list">${state.placeResults.length?state.placeResults.map((p,i)=>`<button class="replacement-option" data-add-search="${i}"><span class="replacement-icon">${ico('pin',19)}</span><span><strong>${safe(p.name)}</strong><small>${safe(p.address)}</small></span>${ico('plus',17)}</button>`).join(''):catalog.map(p=>`<button class="replacement-option" data-add-catalog="${safe(p.id)}"><span class="replacement-icon">${ico('pin',19)}</span><span><strong>${safe(p.name)}</strong><small>${safe(p.category)} · ${safe(p.description)}</small></span>${ico('plus',17)}</button>`).join('')}</div>`;}
if(type==='node'&&node){body=`<div class="modal-heading"><span class="eyebrow">DAY 0${node.day} · ${safe(node.time)}</span><h2>${safe(node.name)}</h2><p>${safe(node.type)} · ${safe(node.duration)} · ${safe(node.source||'待查询')}</p></div><div class="detail-facts"><div><span>费用</span><strong>${safe(node.costLabel)} ${statusBadge(node.status)}</strong></div><div><span>地点坐标</span><strong>${node.lat!=null?`${Number(node.lat).toFixed(5)}, ${Number(node.lng).toFixed(5)}`:'尚未定位'}</strong></div></div><form id="nodeEditForm" class="modal-form"><input type="hidden" name="nodeId" value="${safe(node.id)}"/><div class="node-edit-grid"><label>计划时间<input name="time" type="time" value="${safe(node.time)}" required/></label><label>停留分钟<input name="duration" type="number" min="10" max="720" value="${parseInt(node.duration)||60}" required/></label></div><label>安排到哪一天<select name="day">${trip().days.map((d,i)=>`<option value="${i+1}" ${node.day===i+1?'selected':''}>第 ${i+1} 天 · ${safe(d.title)}</option>`).join('')}</select></label><label>备注<textarea name="note" rows="3" maxlength="240">${safe(node.note)}</textarea></label><button class="primary-btn">保存地点安排</button></form><div class="modal-actions"><button class="outline-btn" data-action="toggleLock" data-id="${node.id}">${node.locked?'取消锁定':'锁定此站'}</button><button class="outline-btn" data-action="toggleDone" data-id="${node.id}">${node.done?'取消到达':'标记到达'}</button><button class="outline-btn" data-action="replace" data-id="${node.id}">替换</button><button class="danger-btn" data-action="deleteNode" data-id="${node.id}" ${node.locked?'disabled':''}>移除</button></div>`;}
if(type==='replace'&&node){const options=placeCatalog.filter(p=>p.city===trip().destination&&p.name!==node.name);body=`<div class="modal-heading"><span class="eyebrow">EDIT THIS STOP</span><h2>替换 · ${safe(node.name)}</h2><p>选择一个已定位的地点，下一步确认费用和路线变化。</p></div>${node.locked?'<div class="notice warning-notice">地点已锁定，请先取消锁定。</div>':''}<div class="replacement-list">${options.map(p=>`<button class="replacement-option" data-replacement="${safe(p.id)}" ${node.locked?'disabled':''}><span class="replacement-icon">${ico('pin',20)}</span><span><strong>${safe(p.name)}</strong><small>${safe(p.category)} · ${safe(p.description)}</small></span>${ico('arrow',17)}</button>`).join('')}</div>`;}
if(type==='diff'&&node){const option=placeCatalog.find(p=>p.id===state.modal.option);body=option?`<div class="modal-heading"><span class="eyebrow">PREVIEW CHANGE</span><h2>确认地点调整</h2><p>替换后会重新查询这一天的道路路线。</p></div><div class="diff-card"><div><span>原地点</span><strong>${safe(node.name)}</strong><small>${safe(node.time)} · ${safe(node.costLabel)}</small></div><span class="diff-arrow">${ico('arrow',20)}</span><div><span>新地点</span><strong>${safe(option.name)}</strong><small>${safe(node.time)} · 费用待查询</small></div></div><div class="notice">两处真实地理位置不同，实际交通耗时将在保存后重新计算。营业时间和门票待核验。</div><div class="modal-actions"><button class="outline-btn" data-action="backReplace" data-id="${node.id}">继续挑选</button><button class="primary-btn" data-action="commitReplace" data-id="${node.id}" data-option="${safe(option.id)}">确认替换</button></div>`:'';}
if(type==='expense'){body=`<div class="modal-heading"><span class="eyebrow">ADD AN EXPENSE</span><h2>记一笔旅费</h2><p>实际支出与你的规划估算分开记录。</p></div><form id="expenseForm" class="modal-form"><label>花在哪里<input name="name" placeholder="例如：午餐" maxlength="40" required/></label><label>金额（元）<input name="amount" type="number" min="0.01" step="0.01" placeholder="0.00" required/></label><label>类别<select name="category"><option>餐饮</option><option>交通</option><option>住宿</option><option>门票</option><option>其他</option></select></label><button class="primary-btn" type="submit">保存支出</button></form>`;}
if(type==='post'){body=`<div class="modal-heading"><span class="eyebrow">SHARE A MOMENT</span><h2>写下路上的故事</h2><p>这篇动态仅保存在你的浏览器里。</p></div><form id="postForm" class="modal-form"><label>标题<input name="title" maxlength="50" placeholder="给这段回忆起个名字" required/></label><label>地点<input name="city" maxlength="30" value="${safe(trip().destination)}" required/></label><label>故事<textarea name="text" maxlength="500" rows="5" placeholder="那天发生了什么？" required></textarea></label><button class="primary-btn" type="submit">保存本地动态</button></form>`;}
if(type==='profile'){body=`<div class="modal-heading"><span class="eyebrow">YOUR NAME</span><h2>怎么称呼你？</h2></div><form id="profileForm" class="modal-form"><label>昵称<input name="name" maxlength="20" value="${safe(state.name)}" required/></label><button class="primary-btn" type="submit">保存昵称</button></form>`;}
if(type==='story'){const story=[...state.posts,...samplePosts].find(p=>p.id===state.modal.storyId);if(story)body=`<div class="modal-heading"><span class="eyebrow">${safe(story.city)} · 旅途故事</span><h2>${safe(story.title)}</h2><p>来自 ${safe(story.author)}</p></div><img class="story-modal-img" src="${safe(story.image||photos.coffee)}" alt="${safe(story.title)}"/><p class="story-modal-text">${safe(story.text)}</p><button class="outline-btn" data-nav="new">用这段灵感规划行程</button>`;}
if(type==='clear'){body=`<div class="modal-heading"><span class="eyebrow">LOCAL DATA</span><h2>清除本地数据？</h2><p>这会删除当前浏览器中的行程、记账、动态和偏好，无法恢复。</p></div><div class="modal-actions"><button class="outline-btn" data-action="closeModal">再想想</button><button class="danger-btn" data-action="clearData">确认清除</button></div>`;}
return `<div class="modal-backdrop" data-action="closeModal"><div class="modal" role="dialog" aria-modal="true" aria-label="${safe(type)}"><button class="modal-close" data-action="closeModal" aria-label="关闭">${ico('close',20)}</button>${body}</div></div>`;}

function render(){if(map){map.remove();map=null;}const pages={discover:discoverPage,plan:planPage,new:newPage,journey:journeyPage,search:searchPage,booking:marketPage,market:marketPage,community:communityPage,footprints:footprintsPage,profile:profilePage,assistant:assistantPage};$('#app').innerHTML=`${sidebar()}<div class="app-shell">${(pages[state.page]||discoverPage)()}<footer class="asset-credit">目的地实地照片及授权：<a href="assets/IMAGE_CREDITS.md" target="_blank" rel="noopener noreferrer">查看图片来源</a></footer></div>${mobileNav()}${modalHtml()}${assistantWidget()}<div id="toast" aria-live="polite"></div>`;renderToast();if(state.page==='plan'&&state.planView==='map')requestAnimationFrame(initMap);if(state.assistantOpen)requestAnimationFrame(()=>{const el=$('.assistant-pop-messages');if(el)el.scrollTop=el.scrollHeight;});if(state.page==='assistant')requestAnimationFrame(()=>{const el=$('#chatMessages');if(el)el.scrollTop=el.scrollHeight;});}

let map=null, markers=[];
function initMap(){
  const el=$('#map');if(!el)return;
  if(map){map.remove();map=null;}
  if(!window.L){el.innerHTML='<div class="map-fallback">地图组件未加载，仍可查看逐日安排。</div>';$('#mapLoading')?.classList.add('is-hidden');return;}
  const located=allNodes().filter(n=>Number.isFinite(Number(n.lat))&&Number.isFinite(Number(n.lng))&&n.lat!=null&&n.lng!=null);
  const dest=destinations.find(d=>d.name===trip().destination)||{lat:located.length?located.reduce((s,n)=>s+Number(n.lat),0)/located.length:35,lng:located.length?located.reduce((s,n)=>s+Number(n.lng),0)/located.length:105};
  map=L.map(el,{zoomControl:false,scrollWheelZoom:true,zoomAnimation:false,fadeAnimation:false}).setView([dest.lat,dest.lng],12,{animate:false});
  const finishLoading=()=>$('#mapLoading')?.classList.add('is-hidden');
  const loadingMap=map;
  setTimeout(()=>{if(map===loadingMap){const loading=$('#mapLoading');if(loading&&!loading.classList.contains('is-hidden'))loading.textContent='地图暂未加载，请检查网络；逐日安排仍可使用。';}},15000);
  if(L.maplibreGL&&window.maplibregl){
    const layer=L.maplibreGL({style:`https://tiles.openfreemap.org/styles/${state.mapLayer==='positron'?'positron':'bright'}`,interactive:false}).addTo(map);
    layer.getMaplibreMap()?.once('idle',finishLoading);
  }else{
    L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).on('load',finishLoading).addTo(map);
  }
  L.control.zoom({position:'bottomright'}).addTo(map);
  const palette=['#2f604a','#dc8451','#607cad'];
  const visible=allNodes().filter(n=>state.selectedDay==='all'||n.day===state.selectedDay);
  const points=[];markers=[];
  if(state.selectedDay!=='all'&&state.routeDay===state.selectedDay&&state.route){
    state.route.legs.forEach(leg=>{if(leg.geometry?.length){L.polyline(leg.geometry,{color:'#fff',weight:9,opacity:.95,lineCap:'round',lineJoin:'round'}).addTo(map);L.polyline(leg.geometry,{color:'#28764d',weight:5,opacity:.98,lineCap:'round',lineJoin:'round'}).addTo(map);}});
  }
  visible.forEach(n=>{
    if(!Number.isFinite(Number(n.lat))||!Number.isFinite(Number(n.lng))||n.lat===null||n.lng===null)return;
    const index=trip().days[n.day-1].nodes.findIndex(x=>x.id===n.id)+1;
    const html=`<span class="map-stop-pin ${Number(n.lng)>Number(dest.lng)?'reverse':''}"><span class="map-marker ${state.selectedNode===n.id?'selected':''}" style="--marker:${palette[(n.day-1)%3]}">${index}</span>${state.selectedDay==='all'?'':`<span class="map-stop-name">${safe(n.name)}</span>`}</span>`;
    const marker=L.marker([n.lat,n.lng],{icon:L.divIcon({html,className:'xy-pin',iconSize:[34,40],iconAnchor:[17,38]})}).addTo(map);
    marker.bindTooltip(`${safe(n.time)} · ${safe(n.name)}`,{direction:'top',offset:[0,-28]});
    marker.on('click',()=>{state.selectedNode=n.id;state.modal={type:'node',nodeId:n.id};recordEvent('place_view',{city:trip().destination,placeId:n.placeId||'',tags:placeCatalog.find(p=>p.id===n.placeId)?.tags||[]});render();});
    markers.push(marker);points.push([n.lat,n.lng]);
  });
  if(points.length>1)map.fitBounds(points,{padding:[60,60],maxZoom:14,animate:false});else if(points.length)map.setView(points[0],13,{animate:false});
  setTimeout(()=>map?.invalidateSize(),100);
  if(state.selectedDay!=='all'&&state.routeDay!==state.selectedDay&&!state.routeLoading)loadRoute(state.selectedDay);
}
async function loadRoute(dayNumber){
  const nodes=trip().days[dayNumber-1]?.nodes.filter(n=>n.lat!=null&&n.lng!=null)||[];
  if(nodes.length<2){state.route=null;state.routeDay=dayNumber;state.routeError='至少需要两个已定位地点';return;}
  if(staticMode){state.route=null;state.routeDay=dayNumber;state.routeError='网页演示版未连接道路路线服务';render();return;}
  const directKm=nodes.length>1?haversineKm(nodes[0],nodes[nodes.length-1]):0;
  const mode=directKm>4||nodes.some(n=>n.type==='交通')?'auto':'pedestrian';
  state.routeLoading=true;state.routeError='';
  try{
    const response=await fetch('/api/geo/route',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({points:nodes.map(n=>({lat:n.lat,lng:n.lng})),mode})});
    const data=await response.json();if(!response.ok)throw new Error(data.message||'路线不可用');
    if(state.selectedDay!==dayNumber)return;
    state.route=data;state.routeDay=dayNumber;
  }catch(e){if(state.selectedDay!==dayNumber)return;state.route=null;state.routeDay=dayNumber;state.routeError=e.message||'路线服务暂不可用';}
  finally{state.routeLoading=false;if(state.page==='plan'&&state.planView==='map')render();}
}
async function handleAssistant(message){
  const text=String(message||'').trim();if(!text||state.assistantBusy)return;
  const history=state.assistantMessages.map(m=>({role:m.role==='bot'?'assistant':'user',text:m.text}));
  state.assistantMessages.push({role:'user',text});state.assistantBusy=true;render();
  if(staticMode){state.assistantMessages.push({role:'bot',text:answerStaticAssistant(text,trip(),sumPlanned())});state.assistantBusy=false;render();return;}
  try{
    const response=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,page:state.page,profile:state.profile,trip:{title:trip().title,destination:trip().destination,origin:trip().origin,start:trip().start,end:trip().end,budget:trip().budget,plannedCost:sumPlanned(),days:trip().days.map(d=>({title:d.title,nodes:d.nodes.map(n=>({name:n.name,time:n.time,note:n.note,costLabel:n.costLabel,status:n.status}))}))},history})});
    const data=await response.json();if(!response.ok)throw new Error(data.message||'模型服务暂不可用');
    state.assistantMessages.push({role:'bot',text:data.answer});
  }catch(error){state.assistantMessages.push({role:'bot',text:error.message==='尚未配置模型 API Key 和模型名'?'小野的模型接口已预留，但还没有配置模型密钥与模型名。配置前我不会编造智能回答。':`模型服务暂不可用：${error.message}`});}
  state.assistantBusy=false;render();
}
function assistantWidget(){return `<div class="assistant-widget ${state.assistantOpen?'open':''}" ${state.assistantBottom==null?'':`style="--assistant-bottom:${state.assistantBottom}px"`}><button class="assistant-fab" data-action="toggleAssistant" aria-label="${state.assistantOpen?'关闭':'打开'}小野助手">${state.assistantOpen?ico('close',21):ico('spark',23)}<span>${state.assistantOpen?'':'小野助手'}</span></button>${state.assistantOpen?`<section class="assistant-pop" aria-label="小野助手"><div class="assistant-pop-head"><span>${ico('spark',19)} 小野助手</span><small>${state.modelConfigured?(state.modelProvider||'模型已连接'):'模型待配置'}</small></div><div class="assistant-pop-messages">${state.assistantMessages.length?state.assistantMessages.slice(-6).map(m=>`<p class="${m.role}">${safe(m.text)}</p>`).join(''):'<p class="bot">你好！你可以问我当前行程安排、预算或想去的地方。</p>'}${state.assistantBusy?'<p class="bot">正在思考…</p>':''}</div><form id="assistantPopForm"><input name="message" maxlength="240" placeholder="问问小野…" required/><button aria-label="发送">${ico('send',17)}</button></form><button class="assistant-pop-full" data-nav="assistant">打开完整对话 ${ico('arrow',14)}</button></section>`:''}</div>`;}

