if(a==='deleteNode'){for(const day of trip().days){const i=day.nodes.findIndex(n=>n.id===target.dataset.id);if(i>=0&&!day.nodes[i].locked){day.nodes.splice(i,1);trip().version++;invalidateRoute();save();state.modal=null;render();toast('地点已从行程移除');break;}}return;}
if(a==='addImported'){const dayNumber=state.selectedDay==='all'?1:Number(state.selectedDay),day=trip().days[dayNumber-1];let count=0;for(const p of state.importMatches){if(day.nodes.some(n=>n.placeId===p.id||n.name===p.name))continue;const stay=day.nodes.findIndex(n=>n.type==='住宿'||(n.type==='交通'&&n.time==='17:00'));day.nodes.splice(stay<0?day.nodes.length:stay,0,catalogNode(p,dayNumber));count++;}if(count){trip().version++;invalidateRoute();save();}state.modal=null;render();toast(count?`已加入 ${count} 个地点`:'这些地点已经在当天行程中');return;}
if(a==='optimizeDay'){const day=trip().days[Number(state.selectedDay)-1];if(!day)return;const fixed=day.nodes.filter(n=>n.locked||n.type==='交通'||n.type==='住宿'||n.lat==null);const movable=day.nodes.filter(n=>!fixed.includes(n));if(movable.length<2){toast('可调整的已定位地点不足两个');return;}let anchor=fixed.find(n=>n.lat!=null)||movable[0],remaining=[...movable],ordered=[];while(remaining.length){remaining.sort((a,b)=>haversineKm(anchor,a)-haversineKm(anchor,b));anchor=remaining.shift();ordered.push(anchor);}let cursor=0;day.nodes=day.nodes.map(n=>fixed.includes(n)?n:ordered[cursor++]);trip().version++;invalidateRoute();save();render();toast('已按地点距离调整顺序，请核对开放时间');return;}
if(a==='toggleLock'||a==='toggleDone'){const n=allNodes().find(x=>x.id===target.dataset.id);const original=trip().days[n.day-1].nodes.find(x=>x.id===n.id);const key=a==='toggleLock'?'locked':'done';original[key]=!original[key];save();state.modal={type:'node',nodeId:n.id};render();toast(original[key]?key==='locked'?'地点已锁定':'已记录到达':'状态已更新');return;}
if(a==='completeCurrent'){const n=allNodes().find(x=>!x.done)||allNodes()[0];trip().days[n.day-1].nodes.find(x=>x.id===n.id).done=true;save();render();toast(`已记录到达：${n.name}`);return;}
